const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeSambhar = ee.Geometry.Point([75.05, 26.97]).buffer(15000); // Buffer around Lake Sambhar
  const start2018 = '2018-01-01';
  const end2018 = '2018-12-31';
  const start2019 = '2019-01-01';
  const end2019 = '2019-12-31';

  // 2. Data Acquisition - JRC Global Surface Water dataset
  const jrcCollection = ee.ImageCollection('JRC/GSW1_3/YearlyHistory');

  // Get 2018 and 2019 images
  const img2018 = jrcCollection.filterDate(start2018, end2018).first();
  const img2019 = jrcCollection.filterDate(start2019, end2019).first();

  // Check if images exist
  if (!img2018 || !img2019) {
    print("Missing data for one or both years");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count water pixels (water = 2 in JRC classification)
  const water2018 = img2018.select('waterClass').eq(2);
  const water2019 = img2019.select('waterClass').eq(2);

  // Count water pixels
  const count2018 = water2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeSambhar,
    scale: 30,
    maxPixels: 1e9
  }).get('waterClass').getInfo();

  const count2019 = water2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeSambhar,
    scale: 30,
    maxPixels: 1e9
  }).get('waterClass').getInfo();

  // 4. Check for valid pixels
  if (count2018 === 0 || count2019 === 0) {
    print(`Water pixels - 2018: ${count2018}, 2019: ${count2019}`);
    print("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  print(`Water extent (pixels): 2018=${count2018}, 2019=${count2019}`);

  if (count2019 < count2018) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
